function LandingDemoBilling(){const [cart,setCart]=useState<any[]>([]),[client,setClient]=useState(""),[cash,setCash]=useState(0),[transfer,setTransfer]=useState(0),[alias,setAlias]=useState("laesquina.mp"),[done,setDone]=useState<any[]>([]);const catalog=[{id:"1",name:"Milanesa napolitana",price:18500,category:"Platos principales"},{id:"2",name:"Pizza napolitana",price:16500,category:"Pizzas"},{id:"3",name:"Limonada",price:4800,category:"Bebidas"}];const total=cart.reduce((v:number,p:any)=>v+p.price,0);const charge=()=>{if(!total||cash+transfer!==total)return;setDone(v=>[{id:Date.now(),client:client||"Consumidor final",total},...v]);setCart([]);setClient("");setCash(0);setTransfer(0)};return <div className="billingPage mesaLandingDemoBilling"><div className="billingHead"><div><span>FACTURACIÓN · SIMULACIÓN</span><h2>Nueva venta</h2><p>Probá una venta con productos ficticios. No se realiza ningún cobro real.</p></div><div className="billingTotal"><small>TOTAL</small><b>{"$"+total.toLocaleString("es-AR")}</b></div></div><div className="billingLayout"><section><label>Cliente<input value={client} onChange={e=>setClient(e.target.value)} placeholder="Nombre del cliente"/></label><h3>Menú disponible</h3><div className="billingProducts">{catalog.map(p=><button key={p.id} onClick={()=>setCart(v=>[...v,{...p,lineId:Date.now()+Math.random()}])}><span><b>{p.name}</b><small>{p.category}</small></span><strong>{"$"+p.price.toLocaleString("es-AR")}</strong><Plus/></button>)}</div></section><aside><h3>Cuenta</h3>{cart.map(p=><div className="billLine" key={p.lineId}><span>{p.name}</span><b>{"$"+p.price.toLocaleString("es-AR")}</b><button onClick={()=>setCart(v=>v.filter(x=>x.lineId!==p.lineId))}>×</button></div>)}{!cart.length&&<p className="emptyBill">Seleccioná productos del menú.</p>}<div className="billingPay"><label>Efectivo<input type="number" min="0" value={cash||""} onChange={e=>setCash(Math.max(0,Number(e.target.value)||0))}/></label><label>Transferencia<input type="number" min="0" value={transfer||""} onChange={e=>setTransfer(Math.max(0,Number(e.target.value)||0))}/></label>{transfer>0&&<label>Alias<select value={alias} onChange={e=>setAlias(e.target.value)}><option value="laesquina.mp">laesquina.mp · La Esquina SRL</option></select></label>}<p>Restante: {"$"+Math.max(0,total-cash-transfer).toLocaleString("es-AR")}</p><button className="dark" disabled={!total||cash+transfer!==total} onClick={charge}>Confirmar venta de prueba</button></div></aside></div>{done.length>0&&<section className="mesaDemoTransfers"><h3>Ventas simuladas</h3>{done.map(x=><div className="paymentLine" key={x.id}><span>{x.client}</span><b>{"$"+x.total.toLocaleString("es-AR")}</b></div>)}</section>}</div>}
