function LandingNotificationShowcase(){
 const entries=[{message:"Mesa 07 · Martín llamó al mozo: necesita servilletas",type:"call"},{message:"Mesa 14 · Sofía solicita cobrar por transferencia",type:"payment"},{message:"Mesa 03 · Lucía escribió: ¿Me traés aderezos?",type:"message"}];
 const [index,setIndex]=useState(-1);const boardRef=useRef<HTMLDivElement|null>(null);const triggered=useRef(false);
 useEffect(()=>{const node=boardRef.current;if(!node)return;const observer=new IntersectionObserver(items=>{if(items.some(x=>x.isIntersecting)&&!triggered.current){triggered.current=true;setIndex(0);observer.disconnect()}},{threshold:.3});observer.observe(node);return()=>observer.disconnect()},[]);
 const play=(type:string)=>{try{const Ctx=(window as any).AudioContext||(window as any).webkitAudioContext;if(!Ctx)return;const ctx=new Ctx();const patterns:Record<string,{notes:number[],dur:number,gap:number,wave:OscillatorType,volume:number}>={call:{notes:[1000,720,1000,720,1000,720],dur:.17,gap:.22,wave:"square",volume:.14},payment:{notes:[440,880,440,880,440,880,1150],dur:.2,gap:.24,wave:"sawtooth",volume:.13},message:{notes:[1200,950,1200,950],dur:.12,gap:.17,wave:"triangle",volume:.16},kitchen:{notes:[720,960,1200,960,1200,1440],dur:.13,gap:.16,wave:"square",volume:.12},clean:{notes:[360,360,520,360,360,520],dur:.23,gap:.27,wave:"sawtooth",volume:.13}};const p=patterns[type]||patterns.call;void ctx.resume();p.notes.forEach((hz,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();const t=ctx.currentTime+.03+i*p.gap;osc.type=p.wave;osc.frequency.setValueAtTime(hz,t);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(p.volume,t+.015);gain.gain.exponentialRampToValueAtTime(.0001,t+p.dur);osc.connect(gain);gain.connect(ctx.destination);osc.start(t);osc.stop(t+p.dur+.02)});setTimeout(()=>void ctx.close(),p.notes.length*p.gap*1000+500)}catch{}};

 return <section className="mesaNotificationSection section"><div className="mesaNotificationIntro"><span className="tag greenText">ATENCIÓN EN TIEMPO REAL</span><h2>Una notificación distinta para cada momento.</h2><p>Así se ven los avisos reales del panel del mozo. Al cerrar y silenciar cada notificación aparece la siguiente, con su propio sonido.</p><div className="mesaNotificationSoundLegend"><span>● Llamado</span><span>● Cobro</span><span>● Mensaje</span></div><p className="mesaNotificationInstructions">Demostración sin operaciones reales. Tocá «Cerrar y silenciar» para avanzar.</p></div><div className="mesaNotificationBoard mesaRealAlertDemo" ref={boardRef}><div className="mesaNotificationBoardHead"><div><span className="mesaNotificationBell"><Bell size={22}/></span><div><b>Centro de avisos</b><small>Así recibe los avisos el mozo</small></div></div></div><div className="mesaRealAlertStage">{index>=0&&index<entries.length?<div key={index} className="mesaRealAlertArrival"><MesaWaiterAlert message={entries[index].message} onDismiss={()=>{play(entries[index].type);setIndex(i=>i+1)}}/></div>:index>=entries.length?<div className="mesaRealAlertFinished"><b>✓ Todos los avisos atendidos</b><button type="button" onClick={()=>setIndex(0)}>Volver a probar</button></div>:null}</div><div className="mesaNotificationBoardBottom">Tres avisos ficticios · Mismo diseño que el panel real</div></div></section>
}
function MesaFeaturedRestaurants(){const [revealed,setRevealed]=useState(false);const gridRef=useRef<HTMLDivElement|null>(null);useEffect(()=>{const node=gridRef.current;if(!node)return;const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){setRevealed(true);observer.disconnect()}},{threshold:.22});observer.observe(node);return()=>observer.disconnect()},[]);const cards=[{title:"El Club",type:"Cocina italiana",award:"Destacado de la semana",rating:"4,9",img:"https://images.unsplash.com/photo-1513104890138-7c749659a591?w=700&q=85"},{title:"Casa Nori",type:"Sushi de autor",award:"Mejor atención",rating:"4,8",img:"https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=700&q=85"},{title:"Don Pietro",type:"Parrilla argentina",award:"Plato más elegido",rating:"4,7",img:"https://images.unsplash.com/photo-1544025162-d76694265947?w=700&q=85"},{title:"La Trattoria",type:"Pastas artesanales",award:"Experiencia más valorada",rating:"4,8",img:"https://images.unsplash.com/photo-1473093295043-cdd812d0e601?w=700&q=85"},{title:"Burger Point",type:"Hamburguesas",award:"Revelación de la semana",rating:"4,6",img:"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=700&q=85"}];return <div ref={gridRef} className="mesaFeaturedGrid">{cards.map((c,i)=><article className="mesaFeaturedCard" key={c.title}><div className={"mesaFeaturedPhoto mesaPixelReveal"+(revealed?" mesaPixelsStarted":"")} style={{backgroundImage:"url('"+c.img+"')","--pixel-seed":i} as any}><div className="mesaPixelGrid" aria-hidden="true">{Array.from({length:24},(_,pixel)=><span key={pixel} style={{animationDelay:(i*.18+((pixel*7)%24)*.055)+"s"}}/>)}</div><span className="mesaFeaturedRating">★ {c.rating}</span><span className="mesaFeaturedAward">{i+1<10?"0"+(i+1):i+1} · {c.award}</span></div><div className="mesaFeaturedInfo"><div><b>{c.title}</b><small>{c.type}</small></div><span>↗</span></div></article>)}</div>}

