 const tables=[3,7,14,18,21,22];const [demoLayout,setDemoLayout]=useState({});const tableName=(n:number)=>"Mesa "+String(n).padStart(2,"0");const open=()=>requests.filter(r=>!r.done);const names:Record<number,string>={3:"Lucía",7:"Martín",14:"Sofía",18:"",21:"",22:""};
