function SalonMap({tables,tableRooms={},staff,sessions={},layout={},setLayout,editing=false,setEditing,persist,onTable,compact=false,cleaningTables=[],salons=[{id:"principal",name:"Principal"}],setSalons,activeSalon="principal",setActiveSalon,objects=[],setObjects,onCloud}:any){
 const roomTables=tables.filter((n:string)=>((tableRooms[n]||salons[0]?.id||"principal")===activeSalon));
 const occupied=(n:string,i:number)=>Boolean(sessions[n]?.active)||cleaningTables.includes(n),assigned=(n:string,i:number)=>sessions[n]?.waiter||"";
 const free=roomTables.filter((n:string)=>!occupied(n,tables.indexOf(n))).length,occ=Math.round((roomTables.length-free)/Math.max(roomTables.length,1)*100),key=(n:string)=>activeSalon+":"+n;
 const pos=(n:string,i:number)=>layout[key(n)]||layout[n]||{x:12+(i%4)*25,y:20+Math.floor(i/4)*30};
 const drag=(e:any,id:string,isObject=false)=>{if(!editing||compact)return;e.preventDefault();e.currentTarget.setPointerCapture?.(e.pointerId);const box=e.currentTarget.parentElement.getBoundingClientRect();let raf=0;const move=(ev:PointerEvent)=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{const x=Math.max(12,Math.min(88,(ev.clientX-box.left)/box.width*100)),y=Math.max(12,Math.min(88,(ev.clientY-box.top)/box.height*100));if(isObject)updateObjects((v:any[])=>v.map(o=>o.id===id?{...o,x,y}:o));else setLayout((v:any)=>({...v,[key(id)]:{x,y}}))})};const up=()=>{cancelAnimationFrame(raf);window.removeEventListener("pointermove",move);window.removeEventListener("pointerup",up)};window.addEventListener("pointermove",move,{passive:true});window.addEventListener("pointerup",up,{once:true})};
 const currentObjects=Array.isArray(objects)?objects:(objects?.[activeSalon]||[]);
 const updateObjects=(fn:any)=>{if(!setObjects)return;setObjects((v:any)=>{const base=Array.isArray(v)?{principal:v}:v;return {...base,[activeSalon]:fn(base[activeSalon]||[])}})};
 const rename=(id:string,name:string)=>updateObjects((v:any[])=>v.map(o=>o.id===id?{...o,name}:o));
 const addObject=()=>{const id="obj"+Date.now();updateObjects((v:any[])=>[...v,{id,type:"label",name:"Nueva zona",x:50,y:50}])};
 const removeObject=(id:string)=>updateObjects((v:any[])=>v.filter(o=>o.id!==id));
 const addSalon=async()=>{if(!onCloud){const id="demo-salon-"+Date.now();setSalons?.((v:any[])=>[...v,{id,name:"Salón "+(v.length+1)}]);setActiveSalon?.(id);return}await onCloud("salons","create",{name:"Salón "+(salons.length+1)})};
 const save=async()=>{if(!onCloud){persist?.();setEditing?.(false);return}for(const [key,pos] of Object.entries(layout||{})){const parts=key.split(":");if(parts.length===2){const p:any=pos;await onCloud?.("tables","position",{number:Number(parts[1]),x:p.x,y:p.y})}}for(const room of salons){const {error}=await supabase.rpc("mesa_salon_update",{p_salon:room.id,p_name:room.name,p_objects:(objects||{})[room.id]||[]});if(error){window.alert(error.message);return}}setEditing?.(false)};
 return <div className={"salonExperience "+(compact?"compact":"")}><div className="salonHero"><div><span>MAPA OPERATIVO</span><h2>Tu restaurante, de un vistazo.</h2><p>{editing?"Mové mesas y sectores, editá sus nombres, agregá o eliminá zonas hasta replicar tu restaurante.":"Ubicación, disponibilidad y mozo asignado en tiempo real."}</p></div>{!compact&&<button className={"layoutEdit "+(editing?"saving":"")} onClick={()=>editing?save():setEditing?.(true)}>{editing?"Guardar distribución":"Editar distribución"}</button>}</div>{salons.length>1||editing?<div className="salonSwitcher">{salons.map((r:any)=><button className={activeSalon===r.id?"on":""} key={r.id} onClick={()=>setActiveSalon?.(r.id)}>{editing?<input value={r.name} onClick={e=>e.stopPropagation()} onChange={e=>setSalons((v:any[])=>v.map(x=>x.id===r.id?{...x,name:e.target.value}:x))}/>:r.name}</button>)}{editing&&<button className="addSalon" onClick={addSalon}>+ Agregar salón</button>}</div>:null}<div className="salonMetrics"><article><small>DISPONIBILIDAD</small><b className="mesaMetricValue">{free}</b><span>mesas libres ahora</span></article><article><small>OCUPACIÓN</small><b className="mesaMetricValue">{occ}%</b><span>{roomTables.length-free} de {roomTables.length} mesas</span><i><em style={{width:occ+"%"}}/></i></article><article><small>RESPUESTA PROMEDIO</small><b className="mesaMetricValue">—</b><span>Sin medición disponible</span></article><article><small>HORA PICO ESTIMADA</small><b className="mesaMetricValue">—</b><span>Sin proyección disponible</span></article></div><div className={"floorPlan newPlan "+(editing?"isEditing":"")} style={{minHeight:Math.max(390,Math.ceil(roomTables.length/4)*125+110)+"px"}}>{currentObjects.map((o:any)=><div key={o.id} style={{left:Math.max(10,Math.min(90,Number(o.x)))+"%",top:Math.max(10,Math.min(90,Number(o.y)))+"%"}} className={"floorObject "+o.type} onPointerDown={e=>drag(e,o.id,true)}>{editing?<><input value={o.name} onPointerDown={e=>e.stopPropagation()} onChange={e=>rename(o.id,e.target.value)}/><button onPointerDown={e=>e.stopPropagation()} onClick={()=>removeObject(o.id)}>×</button></>:<>{o.type==="kitchen"&&<ChefHat/>}{o.name}{o.type==="entrance"&&<ArrowRight/>}</>}</div>)}{roomTables.map((n:string,ri:number)=>{const i=tables.indexOf(n),busy=occupied(n,i),p=pos(n,ri),w=assigned(n,i);return <button style={{left:Math.max(13,Math.min(87,Number(p.x)))+"%",top:Math.max(13,Math.min(87,Number(p.y)))+"%","--delay":(i*.035)+"s"} as any} className={"floorTableV2 "+(busy?"busy":"free")} key={n} onPointerDown={e=>drag(e,n)} onClick={()=>!editing&&onTable?.(n)}><div className="tableShape"><span>{n}</span><b>{cleaningTables.includes(n)?"Limpiar":busy?"Ocupada":"Libre"}</b></div><small title={cleaningTables.includes(n)?"Pendiente de habilitación":busy?(w||"En servicio"):"Disponible"}>{cleaningTables.includes(n)?"Pendiente":busy?(w||"En servicio"):"Disponible"}</small></button>})}{editing&&<><button className="addFloorObject" onClick={addObject}>+ Agregar sector</button><div className="editHint">Arrastrá mesas y sectores · tocá los nombres para editarlos</div></>}</div></div>}

function PaymentFlow({method,setMethod,cash,setCash,splitCash,setSplitCash,tip,setTip,onConfirm,total=0,waiter="el mozo"}:any){const change=method==="cash"?Math.max(0,cash-total-tip):0;return <div className="paymentFlow"><span className="payEyebrow">TOTAL DE LA MESA</span><h3>{"$"+total.toLocaleString("es-AR")}</h3><p>¿Cómo vas a pagar?</p><div className="payMethods">{[["cash","Efectivo"],["transfer","Transferencia"],["split","Una parte y una parte"]].map(x=><button key={x[0]} className={method===x[0]?"on":""} onClick={()=>{setMethod(x[0]);setTip(0)}}>{x[1]}</button>)}</div>{method==="cash"&&<label>¿Con cuánto pagás?<div className="moneyInput">$ <input type="number" value={cash||""} onChange={e=>setCash(Number(e.target.value))} placeholder="Ej. 40000"/></div>{cash>=total&&<small>Tu vuelto base es <b>{"$"+(cash-total).toLocaleString("es-AR")}</b></small>}</label>}{method==="split"&&<label>Parte en efectivo<div className="moneyInput">$ <input type="number" max={total} value={splitCash||""} onChange={e=>setSplitCash(Math.min(total,Number(e.target.value)))}/></div><small>Transferencia: <b>{"$"+Math.max(0,total-splitCash).toLocaleString("es-AR")}</b></small></label>}{method&&<div className="tipChoice"><b>{"¿Querés dejarle propina a "+waiter+"?"}</b><div>{[0,2000,5000].map(n=><button key={n} className={tip===n?"on":""} onClick={()=>setTip(n)}>{n===0?"Sin propina":"$"+n.toLocaleString("es-AR")}</button>)}</div><label>Otro monto<input type="number" value={tip||""} onChange={e=>setTip(Math.max(0,Number(e.target.value)))}/></label>{method==="cash"&&cash>=total+tip&&<small>Vuelto final: <b>{"$"+change.toLocaleString("es-AR")}</b></small>}</div>}<button className="phoneBtn" disabled={!method||(method==="cash"&&cash<total+tip)} onClick={onConfirm}>{"Confirmar y llamar a "+waiter}</button></div>}
function ReviewsLive({reviews,staff,type,setType,filter,setFilter,waiter,setWaiter}:any){const rows=reviews.filter((r:any)=>{const rating=Number(type==="restaurant"?r.restaurant_rating:r.waiter_rating||0);const name=staff.find((x:any)=>x.id===r.waiter_id)?.name;return rating>0&&(!filter||rating===filter)&&(type==="restaurant"||waiter==="Todos"||name===waiter)});const ratings=reviews.map((r:any)=>Number(type==="restaurant"?r.restaurant_rating:r.waiter_rating||0)).filter((n:number)=>n>0);const avg=ratings.length?(ratings.reduce((a:number,b:number)=>a+b,0)/ratings.length).toFixed(1).replace(".",","):"—";return <div className="liveModule"><div className="reviewType"><button className={type==="restaurant"?"on":""} onClick={()=>setType("restaurant")}>Restaurante</button><button className={type==="waiter"?"on":""} onClick={()=>setType("waiter")}>Mozos</button></div><div className="filterBar"><button className={!filter?"on":""} onClick={()=>setFilter(0)}>Todas</button>{[5,4,3,2,1].map(n=><button key={n} className={filter===n?"on":""} onClick={()=>setFilter(n)}>{n} ★</button>)}{type==="waiter"&&<select value={waiter} onChange={e=>setWaiter(e.target.value)}><option>Todos</option>{staff.map((x:any)=><option key={x.id}>{x.name}</option>)}</select>}</div><div className="liveStats"><article><small>CALIFICACIÓN REAL</small><strong>{avg}</strong><span>{ratings.length} opiniones registradas</span></article><article><small>VISITAS VERIFICADAS</small><strong>{reviews.filter((r:any)=>r.verified).length}</strong><span>Con confirmación de visita</span></article></div><div className="liveReviews">{rows.map((r:any)=><article key={r.id}><b>{"★".repeat(Number(type==="restaurant"?r.restaurant_rating:r.waiter_rating))}</b><p>{r.comment||"Sin comentario"}</p><small>{r.verified?"✓ Visita verificada":"Opinión registrada"} · {staff.find((x:any)=>x.id===r.waiter_id)?.name||"Restaurante"}</small></article>)}{!rows.length&&<div className="emptyState">Todavía no hay opiniones para estos filtros. Las nuevas reseñas aparecerán cuando se registren.</div>}</div></div>}
function TipsLive({payments,staff,range,setRange,paid,setPaid,persist}:any){const now=new Date(),start=new Date(now);if(range==="7 días")start.setDate(now.getDate()-6);if(range==="Mes")start.setDate(1);if(range==="Año")start.setMonth(0,1);start.setHours(0,0,0,0);const rows=payments.filter((p:any)=>range==="Todo"||new Date(p.created_at||0)>=start);const sum=(arr:any[])=>arr.reduce((n:number,p:any)=>n+Number(p.tip||0),0);const fmt=(n:number)=>"$"+Math.round(n).toLocaleString("es-AR");const today=now.toLocaleDateString("en-CA");return <div className="liveModule"><div className="filterBar">{["Hoy","7 días","Mes","Año","Todo"].map(x=><button key={x} className={range===x?"on":""} onClick={()=>setRange(x)}>{x}</button>)}</div><div className="liveStats"><article><small>PROPINAS REGISTRADAS</small><strong>{fmt(sum(rows))}</strong><span>{rows.filter((p:any)=>Number(p.tip)>0).length} cobros con propina</span></article><article><small>MOZOS CON PROPINAS</small><strong>{new Set(rows.filter((p:any)=>Number(p.tip)>0).map((p:any)=>p.waiter_id)).size}</strong><span>Según pagos registrados</span></article></div><div className="liveReviews">{staff.map((st:any)=>{const amount=sum(rows.filter((p:any)=>p.waiter_id===st.id));return <article key={st.id}><b>{st.name}</b><p>{fmt(amount)}</p><small>{amount>0?"Propinas vinculadas a cobros":"Sin propinas registradas"}</small>{setPaid&&<div className="mesaTipSettlement"><b>{paid?.includes(st.id+":"+today)?"✓ Pagado hoy":"Pendiente de liquidación"}</b><button disabled={!amount||paid?.includes(st.id+":"+today)} onClick={()=>{setPaid((v:string[])=>[...v,st.id+":"+today]);persist?.()}}>{paid?.includes(st.id+":"+today)?"Pagado":"Marcar pagado"}</button></div>}</article>})}{!staff.length&&<div className="emptyState">Todavía no hay personal cargado.</div>}</div></div>}
function PremiumReport({restaurant,payments,sessions,range,setRange,customDate,setCustomDate,calendarOpen,setCalendarOpen,demo=false}:any){const now=new Date(),start=new Date(now);if(range==="7 días")start.setDate(now.getDate()-6);if(range==="Mes")start.setDate(1);if(range==="Año")start.setMonth(0,1);if(range==="Personalizado")start.setTime(new Date(customDate+"T00:00:00").getTime());start.setHours(0,0,0,0);const filtered=payments.filter((p:any)=>new Date(p.created_at||0)>=start&&(range!=="Personalizado"||new Date(p.created_at||0).toDateString()===start.toDateString()));const sum=(key:string)=>filtered.reduce((n:number,p:any)=>n+Number(p[key]||0),0);const total=sum("total"),tips=sum("tip"),cash=filtered.reduce((n:number,p:any)=>n+Number((p.cash_amount ?? (p.method==="cash"?p.total:0)) || 0),0),transfer=filtered.reduce((n:number,p:any)=>n+Number((p.transfer_amount ?? (p.method==="transfer"?p.total:0)) || 0),0),fmt=(n:number)=>"$"+Math.round(n).toLocaleString("es-AR");return <div className="premiumReportWrap"><div className="reportToolbar"><div>{["Hoy","7 días","Mes","Año"].map(x=><button key={x} className={range===x?"on":""} onClick={()=>setRange(x)}>{x}</button>)}<button onClick={()=>setCalendarOpen(!calendarOpen)}>Personalizado</button>{calendarOpen&&<AppCalendar value={customDate} onSelect={(v:string)=>{setCustomDate(v);setRange("Personalizado");setCalendarOpen(false)}} onClose={()=>setCalendarOpen(false)}/>}</div><button className="dark" disabled={demo} title={demo?"Deshabilitado en la demostración":undefined} onClick={()=>{if(!demo)window.print()}}>Imprimir reporte / PDF</button></div><section className="premiumReport" id="premiumReport"><div className="reportBrand"><span>RESUMEN FINANCIERO · {range.toUpperCase()}</span><h3>{restaurant?.name||"Mi restaurante"}</h3><small>Datos registrados · {new Date().toLocaleDateString("es-AR")}</small></div><div className="reportKpis"><article><span>Ventas registradas</span><b>{fmt(total)}</b></article><article><span>Cobros</span><b>{filtered.length}</b></article><article><span>Propinas</span><b>{fmt(tips)}</b></article><article><span>Mesas activas</span><b>{sessions.filter((x:any)=>x.status!=="closed").length}</b></article></div><div className="financeGrid"><div className="paymentBreakdown"><span>MEDIOS DE PAGO</span><div className="paymentLine"><b>Efectivo</b><span>{fmt(cash)}</span></div><div className="paymentLine"><b>Transferencias</b><span>{fmt(transfer)}</span></div></div><div className="cashBox"><span>CONTROL DE CAJA</span><div className="cashFlow">{fmt(cash)}</div><div className="paymentLine"><span>Ventas registradas</span><b>{fmt(total)}</b></div><div className="paymentLine"><span>Propinas</span><b>{fmt(tips)}</b></div><div className="paymentLine"><span>Efectivo registrado</span><b>{fmt(cash)}</b></div></div></div><div className="reportInsight">Los importes y la cantidad de cobros provienen de pagos registrados. Un cobro puede contener varios productos o pedidos y no confirma que cocina los haya entregado. El historial de pedidos cuenta únicamente los marcados como entregados.</div></section></div>}

function AppCalendar({value,onSelect,onClose}:any){return <div className="mesaCalendar tipCalendar"><div><b>Octubre 2026</b><button onClick={onClose}>×</button></div><div className="week">{["L","M","X","J","V","S","D"].map(x=><span key={x}>{x}</span>)}</div><div className="days">{Array.from({length:31},(_,i)=>i+1).map(n=>{const v="2026-10-"+String(n).padStart(2,"0");return <button key={n} className={value===v?"sel":""} onClick={()=>onSelect(v)}>{n}</button>})}</div></div>}
function ProductDialog({product,onClose,onSave}:any){const [name,setName]=useState(product?.name||""),[category,setCategory]=useState(product?.category||"Principales"),[price,setPrice]=useState(product?.price||""),[stock,setStock]=useState(product?.stock??20),[options,setOptions]=useState<any[]>(product?.options||[]),[optionName,setOptionName]=useState(""),[optionPrice,setOptionPrice]=useState("");const addOption=()=>{if(!optionName.trim())return;setOptions(v=>[...v,{id:Date.now(),name:optionName.trim(),price:Number(optionPrice)||0}]);setOptionName("");setOptionPrice("")};return <div className="appDialog productDialog"><div><button className="x" onClick={onClose}>×</button><span className="tag">{product?"EDITAR PRODUCTO":"NUEVO PRODUCTO"}</span><h2>{product?"Actualizar producto":"Agregar al menú"}</h2><label>Nombre<input value={name} onChange={e=>setName(e.target.value)}/></label><div className="productFields"><label>Categoría<input value={category} onChange={e=>setCategory(e.target.value)}/></label><label>Precio base<input type="number" value={price} onChange={e=>setPrice(e.target.value)}/></label><label>Stock disponible<input type="number" min="0" value={stock} onChange={e=>setStock(Number(e.target.value))}/></label></div><div className="optionBuilder"><div><b>Opciones del producto</b><small>Ej.: Combo grande, Combo chico, con papas, doble carne.</small></div>{options.map((o:any)=><div className="optionRow" key={o.id}><span><b>{o.name}</b><small>{o.price>0?"+ $"+o.price.toLocaleString("es-AR"):"Sin adicional"}</small></span><button onClick={()=>setOptions(v=>v.filter(x=>x.id!==o.id))}>Eliminar</button></div>)}<div className="optionInputs"><input placeholder="Nombre de la opción" value={optionName} onChange={e=>setOptionName(e.target.value)}/><input type="number" placeholder="$ adicional" value={optionPrice} onChange={e=>setOptionPrice(e.target.value)}/><button onClick={addOption}>+ Agregar opción</button></div></div><button className="dark wide" onClick={()=>name&&Number(price)>0&&onSave({...(product||{}),name,category,price:Number(price),stock:Number(stock),options,active:Number(stock)>0?(product?.active??true):false})}>Guardar y publicar</button></div></div>}
function KitchenBoard({orders,setOrders,notify,onReady}:any){const [historyOpen,setHistoryOpen]=useState(false);const archived=(orders||[]).filter((o:any)=>["served","cancelled"].includes(o.status));const active=(orders||[]).filter((o:any)=>!["served","cancelled"].includes(o.status));const visible=historyOpen?archived:active;const ping=()=>{try{const C=(window.AudioContext||(window as any).webkitAudioContext),c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=880;g.gain.setValueAtTime(.12,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.45);o.start();o.stop(c.currentTime+.45)}catch{}};const items=(o:any)=>[o.main,...String(o.extra||"").split(" · ").filter(Boolean)];const readyItem=(o:any,item:string)=>{const done=[...(o.readyItems||[])];if(!done.includes(item))done.push(item);setOrders((os:any[])=>{const next=os.map(x=>x.id===o.id?{...x,readyItems:done}:x);return next});onReady?.({id:o.id+"-"+item,table:o.table,text:item+" listo para retirar"});ping();notify("Mesa "+o.table+" · "+item+" listo")};const advance=(o:any)=>{const next=(o.status==="Nuevo"||o.status==="En cola")?"Preparando":"Listo";setOrders((os:any[])=>{const updated=os.map(x=>x.id===o.id?{...x,status:next}:x);return updated});if(next==="Listo"){onReady?.({id:o.id+"-all",table:o.table,text:"Pedido completo listo para retirar"});ping();notify("Mesa "+o.table+" · pedido completo listo")}else notify("Mesa "+o.table+" en preparación")};const printTicket=(o:any)=>{const f=document.createElement("iframe");f.style.cssText="position:fixed;width:0;height:0;border:0";document.body.appendChild(f);const d=f.contentDocument!;d.open();d.write("<html><head><title>Comanda</title><style>@page{margin:8mm}body{font-family:Arial;padding:8px;width:280px}h1{font-size:24px;border-bottom:2px dashed #000;padding-bottom:12px}.items{font-size:18px;line-height:1.7;margin:24px 0}</style></head><body><h1>MESA · COCINA</h1><b>MESA "+o.table+" · "+o.time+"</b><div class=\"items\"><b>"+o.main+"</b><br/>"+o.extra+"</div><small>Comanda #"+o.id+"</small></body></html>");d.close();setTimeout(()=>{f.contentWindow?.focus();f.contentWindow?.print();setTimeout(()=>f.remove(),1000)},120)};return <div className="kitchenPage"><div className="kitchenHead"><div><span>COCINA EN VIVO</span><h2>Comandas</h2><p>Marcá platos individuales o el pedido completo cuando estén listos.</p></div><b>● {active.length} activas</b></div><div className="kitchenViewTabs"><button className={!historyOpen?"selected":""} onClick={()=>setHistoryOpen(false)}>Comandas activas ({active.length})</button><button className={historyOpen?"selected":""} onClick={()=>setHistoryOpen(true)}>Historial ({archived.length})</button></div><div className="kitchenGrid">{visible.map((o:any)=><article key={o.id} className={o.status==="Listo"?"ready":""}><header><b>Mesa {o.table}</b><span>{o.time}</span></header><div className="kitchenItems">{items(o).map((item:string)=><button key={item} className={(o.readyItems||[]).includes(item)?"itemReady":""} disabled={(o.readyItems||[]).includes(item)||o.status==="Listo"} onClick={()=>readyItem(o,item)}><span>{item}</span><b>{(o.readyItems||[]).includes(item)?"Listo ✓":"Marcar listo"}</b></button>)}</div><small>{o.status.toUpperCase()}</small><div className="kitchenActions"><button onClick={()=>advance(o)} disabled={o.status==="Listo"}>{o.status==="Listo"?"Pedido listo ✓":o.status==="Preparando"?"Pedido completo listo":"Preparar pedido"}</button><button onClick={()=>printTicket(o)}>Imprimir ticket</button></div></article>)}</div>{visible.length===0&&<p className="kitchenEmpty">{historyOpen?"Todavía no hay comandas terminadas.":"No hay comandas pendientes."}</p>}</div>}

function AliasManager({aliases,setAliases,persist,notify,saveCloud,payments=[],sessions=[],tables=[]}:any){const [priorityOpen,setPriorityOpen]=useState(false);const [name,setName]=useState(""),[holder,setHolder]=useState(""),[cuit,setCuit]=useState(""),[limit,setLimit]=useState(""),[priority,setPriority]=useState(1);const save=async()=>{if(!name.trim()||!holder.trim()||!cuit.trim()||Number(limit)<=0)return;if(await saveCloud("aliases","create",{name:name.trim(),holder:holder.trim(),cuit:cuit.trim(),limit:Number(limit),priority})){setName("");setHolder("");setCuit("");setLimit("");setPriority(1);notify("Alias agregado")}};return <div className="aliasManager"><div className="menuManagerHead"><div><span className="tag">COBROS POR TRANSFERENCIA</span><h3>Alias</h3><p>Definí titular, CUIT y cuánto puede recibir cada alias. Al alcanzar el límite deja de ofrecerse en caja.</p></div></div><div className="aliasGrid">{aliases.filter((a:any)=>a.active&&Number(a.used)<Number(a.limit)).map((a:any)=>{const left=Math.max(0,a.limit-a.used);return <article key={a.id} className={left<=0?"disabled":""} style={{borderTop:"6px solid "+(["#e64d4d","#f0a51b","#42c66e"][a.priority??1])}}><small>ALIAS · {["PRIORIDAD ALTA","PRIORIDAD MEDIA","PRIORIDAD BAJA"][a.priority??1]}</small><h3>{a.name}</h3><div className="aliasIdentity"><strong>{a.holder||"Titular no configurado"}</strong><span>CUIT {a.cuit||"—"}</span></div><b>{"$"+left.toLocaleString("es-AR")}</b><span>disponibles de {"$"+a.limit.toLocaleString("es-AR")}</span><div className="aliasProgress"><i style={{width:Math.min(100,a.used/a.limit*100)+"%"}}/></div></article>})}<article className="aliasAdd"><small>NUEVO ALIAS</small><input placeholder="ej. caja.restaurante" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="Nombre del titular" value={holder} onChange={e=>setHolder(e.target.value)}/><input placeholder="CUIT · ej. 20-12345678-9" value={cuit} onChange={e=>setCuit(e.target.value)}/><input type="number" placeholder="Límite disponible" value={limit} onChange={e=>setLimit(e.target.value)}/><div className="mesaPriorityField"><label>Prioridad de cobro</label><div className="mesaPriorityPicker"><button type="button" className={"mesaPriorityTrigger "+(priorityOpen?"isOpen":"")} aria-expanded={priorityOpen} onClick={()=>setPriorityOpen(v=>!v)}><span className="mesaPriorityDot" style={{background:["#e64d4d","#f0a51b","#42c66e"][priority]}}/><span>{["Alta · Rojo","Media · Amarillo","Baja · Verde"][priority]}</span><span className="mesaPriorityChevron">{priorityOpen?"▴":"▾"}</span></button>{priorityOpen&&<div className="mesaPriorityMenu">{["Alta · Rojo","Media · Amarillo","Baja · Verde"].map((name,i)=><button key={i} type="button" className={"mesaPriorityOption "+(priority===i?"selected":"")} onClick={()=>{setPriority(i);setPriorityOpen(false)}}><span className="mesaPriorityDot" style={{background:["#e64d4d","#f0a51b","#42c66e"][i]}}/>{name}{priority===i&&<span className="mesaPriorityCheck">✓</span>}</button>)}</div>}</div></div><button disabled={!name.trim()||!holder.trim()||!cuit.trim()||Number(limit)<=0} onClick={save}>Agregar alias</button></article></div><section className="mesaAliasHistory"><h3>Historial de transferencias</h3><p>Operaciones registradas en caja, con importe y horario.</p>{payments.filter((p:any)=>p.alias_id&&Number(p.transfer_amount)>0).sort((a:any,b:any)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()).map((p:any)=>{const al=aliases.find((a:any)=>a.id===p.alias_id),session=sessions.find((x:any)=>x.id===p.session_id),table=tables.find((x:any)=>x.id===session?.table_id);return <article key={p.id}><div><b>{al?.name||"Alias archivado"}</b><small>Mesa {table?.number??"—"} · {new Date(p.created_at).toLocaleString("es-AR")}</small></div><strong>{"$"+Number(p.transfer_amount).toLocaleString("es-AR")}</strong></article>})}{!payments.some((p:any)=>p.alias_id&&Number(p.transfer_amount)>0)&&<p>No hay transferencias registradas.</p>}</section></div>}

function BillingDesk({products,setProducts,aliases,setAliases,staff,tables=[],tableSessions={},onSale,notify,persist}:any){const [client,setClient]=useState(""),[cart,setCart]=useState<any[]>([]),[cash,setCash]=useState(0),[aliasId,setAliasId]=useState<string>(""),[transfer,setTransfer]=useState(0),[pick,setPick]=useState<any>(null),[table,setTable]=useState("");const total=cart.reduce((sum:any,p:any)=>sum+Number(p.price||0),0),remaining=Math.max(0,total-cash-transfer),available=aliases.filter((a:any)=>a.active&&Number(a.limit)-Number(a.used)>=transfer).sort((a:any,b:any)=>(a.priority??1)-(b.priority??1));const add=(p:any)=>{if(p.options?.length)setPick(p);else setCart(v=>[...v,{...p,lineId:Date.now()+Math.random()}])};const addOption=(p:any,o:any)=>{setCart(v=>[...v,{...p,name:p.name+" · "+o.name,price:Number(p.price)+Number(o.price||0),optionId:o.id,lineId:Date.now()+Math.random()}]);setPick(null)};const selectedBillingTable=table||tables.find((n:string)=>!tableSessions[n]?.active)||"";const [charging,setCharging]=useState(false);const [aliasOpen,setAliasOpen]=useState(false);const charge=async()=>{if(charging||total<=0||remaining>0||Math.abs(cash+transfer-total)>0.009||!selectedBillingTable||!tables.includes(selectedBillingTable))return;const a=aliases.find((x:any)=>x.id===aliasId);if(transfer>0&&(!a||transfer>Number(a.limit)-Number(a.used))){notify("El alias no tiene saldo suficiente");return}setCharging(true);const checkoutItems=cart.map((item:any)=>({product_id:String(item.id),quantity:1,...(item.optionId!=null?{option_id:String(item.optionId)}:{})}));const {error}=await supabase.rpc("mesa_checkout",{p_table_number:Number(selectedBillingTable),p_items:checkoutItems,p_cash:cash,p_transfer:transfer,p_alias_id:transfer>0?aliasId:null});setCharging(false);if(error){notify(error.message);return}notify("Cobro confirmado en Supabase · Comanda enviada");await onSale?.();printSaleTicket(client||"Consumidor final",cart,total,cash,transfer);setClient("");setCart([]);setCash(0);setTransfer(0);setAliasOpen(false);setAliasId("");setTable("")};return <div className="billingPage"><div className="billingHead"><div><span>FACTURACIÓN</span><h2>Nueva venta</h2><p>Menú sincronizado con administración. El nombre del cliente no se guarda.</p></div><div className="billingTotal"><small>TOTAL</small><b>{"$"+total.toLocaleString("es-AR")}</b></div></div><div className="billingLayout"><section><label>Cliente<input value={client} onChange={e=>setClient(e.target.value)} placeholder="Nombre del cliente"/></label><label>Mesa disponible<select value={selectedBillingTable} onChange={e=>setTable(e.target.value)}><option value="">Seleccionar mesa</option>{tables.filter((n:string)=>!tableSessions[n]?.active).map((n:string)=><option key={n} value={n}>Mesa {n}</option>)}</select></label><h3>Menú disponible</h3><div className="billingProducts">{products.filter((p:any)=>p.active&&Number(p.stock??1)>0).map((p:any)=><button key={p.id} onClick={()=>add(p)}><span><b>{p.name}</b><small>{p.category}{p.options?.length?" · "+p.options.length+" opciones":""}</small></span><strong>{"$"+p.price.toLocaleString("es-AR")}</strong><Plus/></button>)}</div></section><aside><h3>Cuenta</h3>{cart.map((p:any)=><div className="billLine" key={p.lineId}><span>{p.name}</span><b>{"$"+p.price.toLocaleString("es-AR")}</b><button onClick={()=>setCart(v=>v.filter(x=>x.lineId!==p.lineId))}>×</button></div>)}{!cart.length&&<p className="emptyBill">Seleccioná productos del menú.</p>}<div className="billingPay"><label>Efectivo<input type="number" value={cash||""} onChange={e=>{const n=Math.max(0,Math.min(total,Number(e.target.value)||0));setCash(n);setTransfer(v=>Math.min(v,Math.max(0,total-n)))}}/></label><label>Transferencia<input type="number" value={transfer||""} onChange={e=>setTransfer(Math.max(0,Math.min(Math.max(0,total-cash),Number(e.target.value)||0)))}/></label>{transfer>0&&<><div className="mesaAliasField"><label>Alias</label><div className="mesaAliasPicker"><button type="button" className={"mesaAliasTrigger "+(aliasOpen?"isOpen":"")} onClick={()=>setAliasOpen(v=>!v)} aria-expanded={aliasOpen}><span>{aliasId?aliases.find((a:any)=>a.id===aliasId)?.name||"Seleccionar alias":"Seleccionar alias"}</span><span className="mesaAliasChevron">{aliasOpen?"▴":"▾"}</span></button>{aliasOpen&&<div className="mesaAliasMenu"><div className="mesaAliasMenuTitle">CUENTAS DISPONIBLES</div>{available.length?available.map((a:any)=><button type="button" key={a.id} className={"mesaAliasOption "+(aliasId===a.id?"selected":"")} onClick={()=>{setAliasId(String(a.id));setAliasOpen(false)}}><span className="mesaAliasDot" style={{background:["#e64d4d","#f0a51b","#42c66e"][Math.min(2,Math.max(0,Number(a.priority??1)))]}}/><span className="mesaAliasOptionText"><b>{a.name}</b><small>{a.holder||"Sin titular"} · Disponible: {"$"+Math.max(0,Number(a.limit)-Number(a.used)).toLocaleString("es-AR")}</small></span>{aliasId===a.id&&<span>✓</span>}</button>):<p className="mesaAliasEmpty">No hay alias con saldo suficiente para esta transferencia.</p>}</div>}</div></div>{aliasId&&available.some((x:any)=>x.id===aliasId)&&(()=>{const a=aliases.find((x:any)=>x.id===aliasId);return a?<div className="selectedAlias" style={{borderLeft:"6px solid "+(["#e64d4d","#f0a51b","#42c66e"][Math.min(2,Math.max(0,Number(a.priority??1)))])}}><small>TRANSFERIR A · {["PRIORIDAD ALTA","PRIORIDAD MEDIA","PRIORIDAD BAJA"][Math.min(2,Math.max(0,Number(a.priority??1)))]}</small><b>{a.name}</b><strong>{a.holder||"Titular no configurado"}</strong><span>CUIT {a.cuit||"—"}</span><em>Monto: {"$"+transfer.toLocaleString("es-AR")}</em></div>:null})()}</>}<div className="billingRemaining"><span>Falta cobrar</span><b>{"$"+remaining.toLocaleString("es-AR")}</b></div>{!selectedBillingTable&&<p className="mesaBillingHint">Para cobrar necesitás crear al menos una mesa disponible en Administración.</p>}<button className="dark wide" disabled={charging||!selectedBillingTable||!cart.length||total<=0||remaining>0||Math.abs(cash+transfer-total)>0.009||(transfer>0&&!available.some((a:any)=>a.id===aliasId))} onClick={charge}>{charging?"Procesando cobro...":"Cobrar e imprimir"}</button></div></aside></div>{pick&&<div className="billingOptionModal"><div><button className="x" onClick={()=>setPick(null)}>×</button><small>PERSONALIZAR</small><h3>{pick.name}</h3><button className="optionChoice" onClick={()=>{setCart(v=>[...v,{...pick,lineId:Date.now()+Math.random()}]);setPick(null)}}><span>Producto base</span><b>{"$"+pick.price.toLocaleString("es-AR")}</b></button>{pick.options.map((o:any)=><button className="optionChoice" key={o.id} onClick={()=>addOption(pick,o)}><span>{o.name}</span><b>{o.price?"+ $"+o.price.toLocaleString("es-AR"):"Sin adicional"}</b></button>)}</div></div>}</div>}
function printSaleTicket(client:string,cart:any[],total:number,cash:number,transfer:number){const f=document.createElement("iframe");f.style.cssText="position:fixed;width:0;height:0;border:0";document.body.appendChild(f);const d=f.contentDocument!;d.open();d.write("<html><head><style>@page{margin:8mm}body{font-family:Arial;width:280px;padding:8px}h1{font-size:22px;border-bottom:2px dashed #000;padding-bottom:10px}.row{display:flex;justify-content:space-between;padding:6px 0}.total{font-size:20px;font-weight:bold;border-top:2px dashed #000;margin-top:12px;padding-top:12px}</style></head><body><h1>MESA</h1><b>"+client+"</b><p>"+new Date().toLocaleString("es-AR")+"</p>"+cart.map(p=>"<div class=\"row\"><span>"+p.name+"</span><b>$"+p.price.toLocaleString("es-AR")+"</b></div>").join("")+"<div class=\"row total\"><span>TOTAL</span><b>$"+total.toLocaleString("es-AR")+"</b></div><div class=\"row\"><span>Efectivo</span><b>$"+cash.toLocaleString("es-AR")+"</b></div><div class=\"row\"><span>Transferencia</span><b>$"+transfer.toLocaleString("es-AR")+"</b></div></body></html>");d.close();setTimeout(()=>{f.contentWindow?.focus();f.contentWindow?.print();setTimeout(()=>f.remove(),1000)},120)}

function SetupRestaurant({name,setName,onCreate}:any){return <div className="setupRestaurant"><div><span className="tag">CONFIGURACIÓN INICIAL</span><h1>Empezá con tu restaurante vacío.</h1><p>No cargamos datos de demostración. Creá el restaurante y después agregá manualmente salón, personal, mesas, menú y medios de cobro.</p><label>Nombre del restaurante<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. La Esquina"/></label><button className="dark wide" disabled={!name.trim()} onClick={onCreate}>Crear restaurante</button></div></div>}
function TutorialCenter({tutorials}:any){const fallback=[["01","Configuración inicial","Creá tu restaurante, salón y mesas."],["02","Personal y turnos","Agregá mozos y prepará la operación."],["03","QR y experiencia del cliente","Probá el QR, llamados y cuenta desde el celular."],["04","Menú y cocina","Cargá productos y seguí pedidos en vivo."],["05","Cobros, alias y propinas","Configurá cómo cobrar y registrar propinas."],["06","Reportes y cierre","Revisá caja, medios de pago y cierre diario."]];const list=tutorials.length?tutorials:fallback.map((x,i)=>({id:i,title:x[1],description:x[2],video_url:"",sort_order:i}));return <div className="tutorialCenter"><div className="tutorialHero"><span className="tag">CENTRO DE APRENDIZAJE</span><h2>Dominá Mesa paso a paso.</h2><p>Videos cortos para configurar el restaurante y probar cada flujo completo.</p></div><div className="tutorialGrid">{list.map((t:any,i:number)=><article key={t.id}><div className="tutorialVideo">{t.video_url?<video controls preload="metadata" src={t.video_url}/>:<div className="videoPlaceholder"><i>{String(i+1).padStart(2,"0")}</i><span>Video pendiente</span></div>}</div><small>TUTORIAL {String(i+1).padStart(2,"0")}</small><h3>{t.title}</h3><p>{t.description}</p></article>)}</div></div>}
